 14 // execMarkerScript writes an executable POSIX script into a directory of its
 15 // own and returns the script path plus the path of the "fired" file the script
 16 // creates when it runs. The script finds that file through $0 rather than an
 17 // embedded path, so no temporary directory ever has to survive being quoted
 18 // into a shell word — git runs core.fsmonitor through `sh -c`, where a path is
 19 // shell input rather than an argv element.
 20 func execMarkerScript(t *testing.T, name string, exitCode int) (script, marker string) {
 21     t.Helper()
 22     dir := t.TempDir()
