197 // signCommitHeader rewrites HEAD as a byte-identical commit carrying a bogus
198 // `gpgsig` header, which is all git needs to attempt signature verification.
199 // No real key is involved: the point is reaching gpg.program at all.
200 func signCommitHeader(t *testing.T, repo string) {
201     t.Helper()
202     raw := gitStdout(t, repo, "cat-file", "commit", "HEAD")
203     headerEnd := bytes.Index(raw, []byte("\n\n"))
204     if headerEnd < 0 {
205         t.Fatalf("commit object has no header/message separator: %q", raw)
206     }
207     const gpgsig = "gpgsig -----BEGIN PGP SIGNATURE-----\n \n ZmFrZQ==\n -----END PGP SIGNATURE-----\n"
208     signed := make([]byte, 0, len(raw)+len(gpgsig))
209     signed = append(signed, raw[:headerEnd+1]...)
210     signed = append(signed, gpgsig...)
211     signed = append(signed, raw[headerEnd+1:]...)
212 
213     write := exec.Command("git", "hash-object", "-w", "-t", "commit", "--stdin")
214     write.Dir = repo
215     write.Stdin = bytes.NewReader(signed)
216     out, err := write.Output()
217     if err != nil {
218         t.Fatalf("git hash-object: %v", err)
219     }
220     newCommit := string(bytes.TrimSpace(out))
221     branch := string(bytes.TrimSpace(gitStdout(t, repo, "symbolic-ref", "HEAD")))
222     git(t, repo, "update-ref", branch, newCommit)
223 }
